import json
import subprocess
import sys

deps = {"api": ["core"], "cli": ["api"], "core": [], "docs": ["core"]}
run = subprocess.run(
    [sys.executable, "build/order.py"],
    input=json.dumps(deps), text=True, capture_output=True,
)
if run.returncode:
    raise SystemExit(run.stderr)
actual = run.stdout.splitlines()
remaining = {name: set(items) for name, items in deps.items()}
expected = []
while remaining:
    ready = sorted(name for name, items in remaining.items()
                   if items <= set(expected))
    if not ready:
        raise SystemExit("dependency cycle")
    expected.append(ready[0])
    del remaining[ready[0]]
if actual != expected:
    raise SystemExit(f"one target per line in this order: {expected}")
print("output format and dependency order are valid")

