#!/usr/bin/env python3
import json
from pathlib import Path

position = json.loads(Path("data/position.json").read_text())
board = position["board"]
row, col, player = position["row"], position["col"], position["player"]

def wins():
    for dr, dc in ((0, 1), (1, 0), (1, 1), (1, -1)):
        total = 1
        for step in (-1, 1):
            r, c = row + step * dr, col + step * dc
            while 0 <= r < 6 and 0 <= c < 7 and board[r][c] == player:
                total += 1
                r += step * dr
                c += step * dc
        if total >= 4:
            return True
    return False

result = json.loads(Path("out/win.json").read_text(encoding="utf-8"))
if set(result) != {"wins"} or result["wins"] is not wins():
    raise SystemExit("output format or computed value differs")
print("output format and computed value are valid")

