import heapq, json, sys

edges = [("Harbor", "Museum", 4), ("Harbor", "Market", 2), ("Market", "Museum", 1), ("Museum", "Depot", 3), ("Market", "Depot", 7)]
graph = {}
for a, b, weight in edges:
    graph.setdefault(a, []).append((b, weight))
    graph.setdefault(b, []).append((a, weight))
dist, routes = {"Harbor": 0}, {"Harbor": ["Harbor"]}
queue = [(0, "Harbor")]
while queue:
    cost, node = heapq.heappop(queue)
    if cost != dist[node]:
        continue
    for neighbor, weight in graph[node]:
        candidate = cost + weight
        if candidate < dist.get(neighbor, float("inf")):
            dist[neighbor] = candidate
            routes[neighbor] = routes[node] + [neighbor]
            heapq.heappush(queue, (candidate, neighbor))
output = json.load(sys.stdin)
if set(output) != {"stops", "minutes"} or output["stops"] != routes["Depot"] or output["minutes"] != round(dist["Depot"], 1):
    raise SystemExit("Output format or route value is incorrect")

