import json
import sys
from collections import defaultdict

totals = defaultdict(lambda: [0, 0])
with open("data/weekly.csv", encoding="utf-8") as source:
    for site, raw in (line.rstrip("\n").split(",") for line in source.readlines()[1:]):
        totals[site][0 if 0 <= float(raw) <= 50 else 1] += 1
actual = json.load(sys.stdin)
computed = [
    {"site": site, "normal_count": counts[0], "out_of_range_count": counts[1]}
    for site, counts in sorted(totals.items())
]
if actual != computed:
    raise SystemExit("output differs from computed weekly counts")

