# Calendar task
Input JSON contains `day_start`, `day_end`, and `busy_intervals`; every interval lies within the day. Print one JSON object with `busy` and `free` arrays, each containing `[start, end]` ISO timestamp pairs.

--- check_output.py ---
from datetime import datetime
import json, sys
from pathlib import Path
data = json.loads(Path("calendar/sample.json").read_text())
parse = lambda value: datetime.fromisoformat(value.replace("Z", "+00:00"))
stamp = lambda value: value.isoformat().replace("+00:00", "Z")
busy = []
for start, end in sorted((parse(a), parse(b)) for a, b in data["busy_intervals"]):
    if busy and start <= busy[-1][1]:
        busy[-1][1] = max(busy[-1][1], end)
    else:
        busy.append([start, end])
free = []
cursor, finish = parse(data["day_start"]), parse(data["day_end"])
for start, end in busy:
    if cursor < start:
        free.append([cursor, start])
    cursor = max(cursor, end)
if cursor < finish:
    free.append([cursor, finish])
reference = {"busy": [[stamp(a), stamp(b)] for a, b in busy],
             "free": [[stamp(a), stamp(b)] for a, b in free]}
output = json.load(sys.stdin)
if set(output) != {"busy", "free"}: raise SystemExit("Required keys: busy, free")
if output != reference: raise SystemExit("Interval values differ")

