#!/usr/bin/env python3
import subprocess

query = 'SELECT datname FROM pg_database WHERE datistemplate = false AND datallowconn = true ORDER BY datname COLLATE "C";'
source = subprocess.run(["psql", "-At", "-c", query], text=True, capture_output=True)
if source.returncode != 0:
    raise SystemExit("database listing returned nonzero status")
names = source.stdout.splitlines()
result = subprocess.run(["bash", "scripts/pg_dump_all.sh"], capture_output=True)
output = result.stdout.decode()
if result.returncode != 0:
    raise SystemExit("script returned nonzero status")
if output.splitlines() != names or not output.endswith("\n"):
    raise SystemExit("stdout format mismatch")

