import ipaddress
import json
import pathlib
import sys

counts = {"valid_count": 0, "invalid_count": 0}
for line in pathlib.Path("access.txt").read_text().splitlines():
    value = line.strip()
    if not value:
        continue
    try:
        ipaddress.ip_address(value)
    except ValueError:
        counts["invalid_count"] += 1
    else:
        counts["valid_count"] += 1
actual = json.load(sys.stdin)
if set(actual) != set(counts):
    raise SystemExit("wrong fields")
if actual != counts:
    raise SystemExit("wrong counts")

