import json, subprocess

def parse(text):
    p = text.split(".")
    if len(p) != 4 or any(not x.isdigit() for x in p): return False, None
    n = [int(x) for x in p]
    if any(x > 255 for x in n): return False, None
    return True, sum(x << s for x, s in zip(n, (24, 16, 8, 0)))

for address in ("203.0.113.7", "10.20.30.40", "256.1.2.3"):
    output = subprocess.run(["/tmp/ipv4", address], capture_output=True, text=True, check=True).stdout
    actual = json.loads(output)
    valid, value = parse(address)
    if actual != {"valid": valid, "value": value}:
        raise ValueError("invalid output")

