import json
import subprocess
import sys
from pathlib import Path

edges = json.loads(Path("data/follows.json").read_text())
users = {name for pair in edges for name in pair}
follows = {tuple(pair) for pair in edges}
adjacency = {name: set() for name in users}
for left, right in follows:
    if (right, left) in follows:
        adjacency[left].add(right)
        adjacency[right].add(left)

groups, seen = [], set()
for start in sorted(users):
    if start in seen:
        continue
    todo, group = [start], []
    seen.add(start)
    while todo:
        name = todo.pop()
        group.append(name)
        for neighbor in adjacency[name] - seen:
            seen.add(neighbor)
            todo.append(neighbor)
    groups.append(sorted(group))
run = subprocess.run([sys.executable, "social/groups.py"], capture_output=True, text=True, check=True)
actual = json.loads(run.stdout)
if set(actual) != {"clusters"} or actual["clusters"] != groups:
    raise SystemExit("output format or groups do not match")

