import csv, json, subprocess, sys

with open("rooms/meetings.csv", newline="") as source:
    meetings = list(csv.DictReader(source))
run = subprocess.run([sys.executable, "rooms/assign.py"], capture_output=True, text=True)
result = json.loads(run.stdout)
if set(result) != {"room_count", "assignments"}:
    raise ValueError("output fields must be room_count and assignments")
assignments = result["assignments"]
ids = {row["meeting"] for row in meetings}
if set(assignments) != ids:
    raise ValueError("assignment IDs differ from input")
events = sorted((int(row[key]), delta) for row in meetings for key, delta in (("start", 1), ("end", -1)))
active = peak = 0
for _, change in events:
    active += change
    peak = max(peak, active)
for i, left in enumerate(meetings):
    for right in meetings[i + 1:]:
        overlap = max(int(left["start"]), int(right["start"])) < min(int(left["end"]), int(right["end"]))
        if overlap and assignments[left["meeting"]] == assignments[right["meeting"]]:
            raise ValueError("overlapping meetings share a room")
if result["room_count"] != peak or len(set(assignments.values())) != peak:
    raise ValueError("room count is not minimal")
print("output format and assignments are valid")

