import json, sys
markers = [("oak", 0, 0), ("pine", 3, 0), ("birch", 12, 0), ("ash", 15, 0)]
radius = 4
parent = list(range(len(markers)))

def root(i):
    return i if parent[i] == i else root(parent[i])

for i, a in enumerate(markers):
    for j, b in enumerate(markers[:i]):
        if (a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2 <= radius ** 2:
            parent[root(i)] = root(j)
groups = {}
for i, marker in enumerate(markers):
    groups.setdefault(root(i), []).append(marker[0])
ordered = sorted((sorted(ids) for ids in groups.values()), key=lambda ids: ids[0])
actual = json.load(sys.stdin)
if actual != {"clusters": ordered}:
    raise SystemExit("output differs from calculated clusters")

