#!/usr/bin/env python3
from pathlib import Path
import subprocess
import tempfile

root = Path(__file__).resolve().parent
sizes = {"zeta.log": 50 * 1024 * 1024 + 1, "alpha.log": 12}
with tempfile.TemporaryDirectory() as name:
    folder = Path(name)
    for filename, size in sizes.items():
        with (folder / filename).open("wb") as stream:
            stream.truncate(size)
    result = subprocess.run(
        ["bash", str(root / "scripts/rotate.sh"), str(folder)],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE,
    )
    wanted = sorted(
        str(folder / filename)
        for filename, size in sizes.items()
        if size > 50 * 1024 * 1024
    )
    text = result.stdout.decode("utf-8")
    if result.returncode or not text.endswith("\n") or text.splitlines() != wanted:
        raise SystemExit("stdout format mismatch")

